#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-23

# test-agent-plugins-manifest.sh — Agent Plugins 1.0.0 manifest invariants.
#
# Each built plugin carries TWO manifests, and the whole point is that they are
# two files rather than one:
#
#   .claude-plugin/plugin.json   Claude Code. Carries skills/commands/workflows
#                                path keys that Claude Code understands.
#   plugin.json  (plugin root)   agent-plugins.org 1.0.0. Its canonical schema
#                                is `additionalProperties: false`, so those
#                                three keys are forbidden here.
#
# Spec 4.1 and 5.1 put the Agent Plugins manifest at `plugin.json` in the plugin
# root; Claude Code reads `.claude-plugin/plugin.json`. Different paths, so both
# files are exactly right and neither compromises for the other.
#
# What this guards, and why each check exists:
#
#   1. The root manifest exists at all. It is generated by build-plugins.sh; if
#      someone edits plugins/ by hand and the build is not re-run, it vanishes.
#   2. No key outside the ten the schema permits. This is the check that would
#      have caught the tempting shortcut of putting $schema on the Claude Code
#      manifest: that file names a schema it fails, in three places.
#   3. $schema is the canonical constant. The schema declares it a `const`, so
#      a typo or a version bump is a hard failure, not a warning.
#   4. Shared fields are byte-identical to the Claude Code manifest. Two
#      manifests describing one plugin is a drift surface; the generator
#      derives one from the other, and this proves it still does.
#
# The permitted-key list is embedded rather than fetched. The spec is explicit
# that "Clients MUST NOT retrieve a schema while loading a plugin", and a test
# that needs the network to decide is a test that goes red when a CDN does.
# Source of truth: https://agent-plugins.org/schemas/1.0.0/plugin.schema.json

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PLUGINS_DIR="$REPO_ROOT/plugins"
FAILURES=0

CANONICAL_SCHEMA="https://agent-plugins.org/schemas/1.0.0/plugin.schema.json"
# The ten permitted top-level fields, spec 5.2. Closed set.
PERMITTED='["$schema","name","version","description","author","homepage","repository","license","keywords","extensions"]'
# author is itself additionalProperties:false over exactly these three.
AUTHOR_PERMITTED='["name","email","url"]'
# Spec 5.3: name is REQUIRED alongside $schema.
REQUIRED='["$schema","name"]'

fail() {
  echo "FAIL: $1"
  FAILURES=$((FAILURES + 1))
}

if [[ ! -d "$PLUGINS_DIR" ]]; then
  echo "SKIP: plugins/ not built (run npm run build)"
  exit 0
fi

PLUGIN_COUNT=0

for plugin_dir in "$PLUGINS_DIR"/*/; do
  [[ -d "$plugin_dir" ]] || continue
  plugin_name="$(basename "$plugin_dir")"
  cc_manifest="$plugin_dir.claude-plugin/plugin.json"
  ap_manifest="$plugin_dir/plugin.json"

  # Only plugins Claude Code recognizes are in scope; a stray directory is not.
  [[ -f "$cc_manifest" ]] || continue
  PLUGIN_COUNT=$((PLUGIN_COUNT + 1))

  # 1. Exists and parses. jq's stderr is captured and reported, never dropped:
  #    "invalid JSON" with no reason is a worse test failure than no test.
  if [[ ! -f "$ap_manifest" ]]; then
    fail "$plugin_name: no Agent Plugins manifest at plugin.json in the plugin root (re-run npm run build)"
    continue
  fi
  if ! parse_err="$(jq empty "$ap_manifest" 2>&1 >/dev/null)"; then
    fail "$plugin_name: plugin.json is not valid JSON: $parse_err"
    continue
  fi

  # 2. Closed schema: no key outside the permitted ten.
  extra="$(jq -r --argjson ok "$PERMITTED" \
    '[keys_unsorted[] | select(. as $k | $ok | index($k) | not)] | join(", ")' \
    "$ap_manifest")"
  if [[ -n "$extra" ]]; then
    fail "$plugin_name: plugin.json has fields the closed schema forbids: $extra"
  fi

  author_extra="$(jq -r --argjson ok "$AUTHOR_PERMITTED" \
    '(.author // {}) | [keys_unsorted[] | select(. as $k | $ok | index($k) | not)] | join(", ")' \
    "$ap_manifest")"
  if [[ -n "$author_extra" ]]; then
    fail "$plugin_name: plugin.json author has forbidden fields: $author_extra"
  fi

  # 3. Required fields, and $schema is the canonical constant.
  # `$k` is bound before the pipe on purpose: inside `has(...)` a bare `.` is
  # re-bound to the piped object, so `has(.)` asks whether the manifest has
  # itself as a key and jq dies with "Cannot check whether object has a object key".
  missing="$(jq -r --argjson req "$REQUIRED" \
    '. as $m | [$req[] | . as $k | select(($m | has($k)) | not)] | join(", ")' "$ap_manifest")"
  if [[ -n "$missing" ]]; then
    fail "$plugin_name: plugin.json missing required field(s): $missing"
  fi

  actual_schema="$(jq -r '."$schema" // ""' "$ap_manifest")"
  if [[ "$actual_schema" != "$CANONICAL_SCHEMA" ]]; then
    fail "$plugin_name: \$schema is '$actual_schema', expected the canonical '$CANONICAL_SCHEMA'"
  fi

  # name: non-empty, <= 64 chars, lowercase/digits/dot/hyphen, no -- or ..,
  # and no leading or trailing separator (spec 5.3 pattern).
  name="$(jq -r '.name // ""' "$ap_manifest")"
  if [[ ! "$name" =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$ ]] \
    || [[ "$name" == *--* ]] || [[ "$name" == *..* ]] || (( ${#name} > 64 )); then
    fail "$plugin_name: name '$name' does not satisfy the Agent Plugins name pattern"
  fi

  # 4. No drift: every shared field is byte-identical across the two manifests.
  drift="$(jq -rn \
    --slurpfile ap "$ap_manifest" \
    --slurpfile cc "$cc_manifest" \
    '[$ap[0] | keys_unsorted[]
      | select(. != "$schema")
      | . as $k
      | select(($cc[0] | has($k)) and ($ap[0][$k] != $cc[0][$k]))] | join(", ")')"
  if [[ -n "$drift" ]]; then
    fail "$plugin_name: field(s) differ between the two manifests: $drift"
  fi

  # The three Claude Code path keys must NOT have leaked into the portable one.
  leaked="$(jq -r '[.skills, .commands, .workflows] | map(select(. != null)) | length' "$ap_manifest")"
  if [[ "$leaked" != "0" ]]; then
    fail "$plugin_name: Claude Code path keys leaked into the Agent Plugins manifest"
  fi
done

if (( PLUGIN_COUNT == 0 )); then
  fail "no plugins found under plugins/ (expected at least one)"
fi

if (( FAILURES > 0 )); then
  echo ""
  echo "$FAILURES failure(s) across $PLUGIN_COUNT plugin(s)"
  exit 1
fi

echo "PASS: $PLUGIN_COUNT plugin(s) carry a conforming Agent Plugins 1.0.0 manifest"
